using System;using System.Linq;using System.Security.Cryptography;using BeamScheduleFormatter;
class AccessProtocolTests{static int checks;static void Check(bool value,string message){if(!value)throw new Exception(message);checks++;}static void Main(){using(var rsa=new RSACryptoServiceProvider(2048)){rsa.PersistKeyInCsp=false;string key=rsa.ToXmlString(true),pub=rsa.ToXmlString(false),request=AccessCodes.NewRequest();for(int apps=1;apps<=AccessCodes.AllApps;apps++){if(!ProgramAccess.ValidMask(apps))continue;string code=AccessCodes.Generate(request,key,apps);Check(code.StartsWith("BA4."),"Precise grants require new protocol");Check(AccessCodes.Verify(request,code,pub),"Signed selection rejected");var p=code.Split('.');p[3]=apps==7?"1":"7";Check(!AccessCodes.Verify(request,string.Join(".",p),pub),"App selection tampering accepted");Check(!AccessCodes.Verify(AccessCodes.NewRequest(),code,pub),"Wrong request accepted");Check(!AccessCodes.Verify(request,AccessCodes.GenerateAt(request,key,DateTime.UtcNow.AddHours(-9),apps),pub),"Expired code accepted");}foreach(int program in ProgramAccess.Ids){foreach(int other in ProgramAccess.Ids)Check(ProgramAccess.Allows(program,other)==(program==other),"Program grant leaks into another tool");Check(ProgramAccess.Allows(program,8),"Project Information omitted");}
foreach(int invalid in new[]{0,8,15,120,8192,8704,-1}){bool bad=false;try{AccessCodes.Generate(request,key,invalid);}catch{bad=true;}Check(bad,"Invalid/reserved mask accepted");}Check(ProgramAccess.ValidMask(ProgramAccess.BeamDeflection)&&ProgramAccess.ValidMask(ProgramAccess.All),"Beam Deflection Check (256) is a valid program bit");
// Old signatures retain their original payload; a legacy formatter grant covers both formatters only.
long stamp=(long)(DateTime.UtcNow-new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc)).TotalSeconds;string times=stamp+"."+(stamp+28800);foreach(int mask in new[]{1,4,7}){byte[] data=System.Text.Encoding.UTF8.GetBytes("BEAM-ACCESS-V3|"+request+"|"+times+"|"+mask);string old="BA3."+times+"."+mask+"."+Convert.ToBase64String(rsa.SignData(data,CryptoConfig.MapNameToOID("SHA256")));Check(AccessCodes.Verify(request,old,pub),"Legacy code rejected");int restored=AccessCodes.AppsForApprovedCode(old);Check(!ProgramAccess.Allows(restored,16)&&!ProgramAccess.Allows(restored,32),"Legacy grants must not unlock new design programs");Check(ProgramAccess.Allows(restored,64)==((mask&1)!=0),"Legacy slab formatter access changed");}
DateTime now=new DateTime(2026,10,26,0,0,0,DateTimeKind.Utc),end;
string cert=AccessCodes.GenerateCertificationAt(key,Engine.Version,now);
Check(AccessCodes.ValidateAt("",cert,pub,now,out end),"Certification requires a request");
Check(end==now.AddDays(30),"Certification duration");
Check(AccessCodes.ValidateAt(AccessCodes.NewRequest(),cert,pub,now.AddDays(29),out end),"Certification on another PC rejected");
Check(!AccessCodes.ValidateAt(request,cert,pub,now.AddDays(30),out end),"Certification expired boundary accepted");
Check(!AccessCodes.ValidateAt(request,cert,pub,now.AddMinutes(-6),out end),"Future certification accepted");
Check(!AccessCodes.ValidateForVersionAt(request,cert,pub,now,Engine.Version+"1",out end),"Wrong version accepted");
using(var other=new RSACryptoServiceProvider(2048)){other.PersistKeyInCsp=false;Check(!AccessCodes.ValidateAt(request,cert,other.ToXmlString(false),now,out end),"Wrong signer accepted");}
string[] cp=cert.Split('.');
foreach(int field in new[]{0,1,2,3,4,5}){var changed=(string[])cp.Clone();changed[field]=field==0?"BA3":field==3?"1":field==4?Engine.Version.Replace(".","-")+"1":field==5?"AAAA":"0";Check(!AccessCodes.ValidateAt(request,string.Join(".",changed),pub,now,out end),"Certification tampering accepted: "+field);}
var extended=(string[])cp.Clone();extended[2]=(long.Parse(cp[2])+1).ToString();Check(!AccessCodes.ValidateAt(request,string.Join(".",extended),pub,now,out end),"Extended certification accepted");
foreach(string invalid in new[]{"", "1.4", "1.4.27.0", "01.4.27", "1.4.-1", "1.4.65536", "1-4-27"}){bool bad=false;try{AccessCodes.GenerateCertificationAt(key,invalid,now);}catch(ArgumentException){bad=true;}Check(bad,"Invalid certification version accepted");}
bool rejected=false;try{AccessCodes.Generate(request,key,0);}catch{rejected=true;}Check(rejected,"No-app approval accepted");}TimeSpan clock=TimeSpan.Zero;var lease=new AccessLease(()=>clock);lease.Start();Check(lease.IsValid,"Fresh lease");clock=TimeSpan.FromHours(8);Check(!lease.IsValid,"Eight-hour expiry");clock=TimeSpan.Zero;lease.Start(TimeSpan.FromDays(30));Check(!lease.IsValid,"Normal access extended to 30 days");lease.Start(TimeSpan.FromDays(30),true);Check(lease.IsValid,"Certification lease rejected");clock=TimeSpan.FromHours(8);Check(lease.IsValid,"Certification stopped after eight hours");clock=TimeSpan.FromDays(30);Check(!lease.IsValid,"Certification lease did not expire");
/* v1.50.13: DTCE- request prefix (BEAM- still valid) and separate access for Bar Bending Schedule, Truss Support, Strap Foundation and Earthquake / RSA */
Check(AccessCodes.NewRequest().StartsWith("DTCE-")&&AccessCodes.ValidRequest(AccessCodes.NewRequest()),"new requests start with DTCE-");Check(AccessCodes.ValidRequest("BEAM-0123456789ABCDEF0123456789ABCDEF01234567"),"older BEAM- requests stay valid");Check(!AccessCodes.ValidRequest("XXXX-0123456789ABCDEF0123456789ABCDEF01234567"),"other prefixes rejected");
foreach(int app in new[]{ProgramAccess.TrussSupport,ProgramAccess.StrapFoundation,ProgramAccess.EarthquakeRsa,ProgramAccess.BarBendingSchedule}){Check(ProgramAccess.ValidMask(app)&&ProgramAccess.Ids.Contains(app),"new app has its own checkbox");Check(!ProgramAccess.Allows(ProgramAccess.TrussConnections|ProgramAccess.WindDesign|ProgramAccess.ProgramOfWorks,app),"new app needs its own grant");Check(ProgramAccess.Allows(app,app),"new app granted");}
Check(ProgramAccess.Names.Length==ProgramAccess.Ids.Length&&ProgramAccess.Ids.Aggregate(0,(m,x)=>m|x)==ProgramAccess.All,"names, ids and mask agree");Check(ProgramAccess.ForSheet("Truss-Support")==ProgramAccess.TrussSupport&&ProgramAccess.ForSheet("Strap-Footing")==ProgramAccess.StrapFoundation&&ProgramAccess.ForSheet("RSA-Curve")==ProgramAccess.EarthquakeRsa&&ProgramAccess.ForSheet("Truss-Connections")==ProgramAccess.TrussConnections,"design sheets map to their own access");
Console.WriteLine("PASS: "+checks+" signed app selection, request binding, tamper rejection and expiry checks. Ephemeral test keys only.");}}

